const test = require("node:test");
const assert = require("node:assert/strict");
const express = require("express");

const app = express();
app.use(express.json());

const TAREFAS = [];

app.get("/tarefas", (req, res) => res.json(TAREFAS));

app.post("/tarefas", (req, res) => {
  const titulo = req.body?.titulo;
  if (typeof titulo !== "string" || titulo.trim().length < 3) {
    return res.status(400).json({ erro: "dados inválidos", campos: ["titulo"] });
  }
  const tarefa = { id: TAREFAS.length + 1, titulo: titulo.trim(), feita: false };
  TAREFAS.push(tarefa);
  res.status(201).json(tarefa);
});

// ── os testes ────────────────────────────────────────────
// sobe numa porta sorteada (o 0), usa e derruba
async function comServidor(usar) {
  const servidor = app.listen(0);
  try {
    await usar(`http://127.0.0.1:${servidor.address().port}`);
  } finally {
    servidor.close();
  }
}

const postar = (base, corpo) =>
  fetch(`${base}/tarefas`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(corpo),
  });

test("começa vazia", async () => {
  TAREFAS.length = 0;
  await comServidor(async (base) => {
    const r = await fetch(`${base}/tarefas`);
    assert.equal(r.status, 200);
    assert.deepEqual(await r.json(), []);
  });
});

test("cria e aparece na lista", async () => {
  TAREFAS.length = 0;
  await comServidor(async (base) => {
    const criada = await postar(base, { titulo: "Escrever teste" });
    assert.equal(criada.status, 201);
    const lista = await fetch(`${base}/tarefas`);
    assert.deepEqual(await lista.json(), [await criada.json()]);
  });
});

test("titulo curto não passa", async () => {
  TAREFAS.length = 0;
  await comServidor(async (base) => {
    const r = await postar(base, { titulo: "ab" });
    assert.equal(r.status, 400);
  });
});

