from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()
TAREFAS = []

class NovaTarefa(BaseModel):
    titulo: str = Field(min_length=3, max_length=120)

@app.get("/tarefas")
def listar():
    return TAREFAS

@app.post("/tarefas", status_code=201)
def criar(nova: NovaTarefa):
    tarefa = {"id": len(TAREFAS) + 1, "titulo": nova.titulo.strip(), "feita": False}
    TAREFAS.append(tarefa)
    return tarefa

cliente = TestClient(app)

def test_cria_com_status_e_corpo():
    TAREFAS.clear()
    resposta = cliente.post("/tarefas", json={"titulo": "  Estudar teste  "})
    assert resposta.status_code == 201
    assert resposta.json() == {"id": 1, "titulo": "Estudar teste", "feita": False}

def test_recusa_titulo_curto():
    TAREFAS.clear()
    assert cliente.post("/tarefas", json={"titulo": "ab"}).status_code == 422

def test_recusa_nao_deixa_lixo():
    TAREFAS.clear()
    cliente.post("/tarefas", json={"titulo": "ab"})
    assert cliente.get("/tarefas").json() == []

if __name__ == "__main__":
    import sys, pytest
    sys.exit(pytest.main([__file__, "-q"]))

