import base64, hashlib, hmac, json, os, secrets, time
from fastapi import Depends, FastAPI, Header, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()
SEGREDO = os.environ.get("APP_SEGREDO", "so-para-teste").encode()
USUARIOS = {"ana@exemplo.com": {"id": 7, "senha": "senha-boa-123"}}   # simplificado
TAREFAS = [{"id": 1, "usuario_id": 9, "titulo": "De outra pessoa"}]

def _b64(d): return base64.urlsafe_b64encode(d).decode().rstrip("=")

def criar_token(uid):
    corpo = _b64(json.dumps({"sub": uid, "exp": int(time.time()) + 3600}).encode())
    return f"{corpo}.{_b64(hmac.new(SEGREDO, corpo.encode(), hashlib.sha256).digest())}"

def ler_token(token):
    try:
        corpo, assinatura = token.split(".")
    except ValueError:
        return None
    esperada = _b64(hmac.new(SEGREDO, corpo.encode(), hashlib.sha256).digest())
    if not hmac.compare_digest(assinatura, esperada):
        return None
    dados = json.loads(base64.urlsafe_b64decode(corpo + "=" * (-len(corpo) % 4)))
    return None if dados["exp"] < time.time() else dados["sub"]

def usuario_atual(authorization: str = Header(default="")) -> int:
    uid = ler_token(authorization.removeprefix("Bearer ")) if authorization.startswith("Bearer ") else None
    if uid is None:
        raise HTTPException(status_code=401, detail="faça login")
    return uid

class Credenciais(BaseModel):
    email: str
    senha: str

@app.post("/login")
def entrar(dados: Credenciais):
    u = USUARIOS.get(dados.email)
    if u is None or not hmac.compare_digest(u["senha"], dados.senha):
        raise HTTPException(status_code=401, detail="e-mail ou senha inválidos")
    return {"token": criar_token(u["id"])}

@app.get("/tarefas")
def listar(uid: int = Depends(usuario_atual)):
    return [t for t in TAREFAS if t["usuario_id"] == uid]

@app.get("/tarefas/{id}")
def uma(id: int, uid: int = Depends(usuario_atual)):
    t = next((t for t in TAREFAS if t["id"] == id), None)
    if t is None:
        raise HTTPException(status_code=404, detail="não encontrada")
    if t["usuario_id"] != uid:
        raise HTTPException(status_code=403, detail="sem permissão")
    return t

# ── o caminho inteiro, num teste só ───────────────────────
cliente = TestClient(app)

def test_fluxo_completo():
    assert cliente.get("/tarefas").status_code == 401            # sem token

    errado = cliente.post("/login", json={"email": "ana@exemplo.com", "senha": "chute"})
    assert errado.status_code == 401                             # senha errada

    entrada = cliente.post("/login", json={"email": "ana@exemplo.com", "senha": "senha-boa-123"})
    assert entrada.status_code == 200
    cabecalho = {"Authorization": f"Bearer {entrada.json()['token']}"}

    assert cliente.get("/tarefas", headers=cabecalho).json() == []   # nada meu ainda
    assert cliente.get("/tarefas/1", headers=cabecalho).status_code == 403   # é de outro
    assert cliente.get("/tarefas/99", headers=cabecalho).status_code == 404

if __name__ == "__main__":
    import sys, pytest
    sys.exit(pytest.main([__file__, "-q"]))       # 1 passed

