from flask import Flask, g, request

app = Flask(__name__)
SEGREDO = os.environ.get("APP_SEGREDO", "so-para-teste").encode()
USUARIOS = {"ana@exemplo.com": {"id": 7, "senha": "senha-boa-123"}}   # simplificado
TAREFAS = [{"id": 1, "usuario_id": 9, "titulo": "De outra pessoa"}]

def _b64(d): return base64.urlsafe_b64encode(d).decode().rstrip("=")

def criar_token(uid):
    corpo = _b64(json.dumps({"sub": uid, "exp": int(time.time()) + 3600}).encode())
    return f"{corpo}.{_b64(hmac.new(SEGREDO, corpo.encode(), hashlib.sha256).digest())}"

def ler_token(token):
    try:
        corpo, assinatura = token.split(".")
    except ValueError:
        return None
    esperada = _b64(hmac.new(SEGREDO, corpo.encode(), hashlib.sha256).digest())
    if not hmac.compare_digest(assinatura, esperada):
        return None
    dados = json.loads(base64.urlsafe_b64decode(corpo + "=" * (-len(corpo) % 4)))
    return None if dados["exp"] < time.time() else dados["sub"]

def exige_login(rota):
    @wraps(rota)
    def dentro(*args, **kwargs):
        cabecalho = request.headers.get("Authorization", "")
        uid = ler_token(cabecalho.removeprefix("Bearer ")) if cabecalho.startswith("Bearer ") else None
        if uid is None:
            return {"erro": "faça login"}, 401
        g.uid = uid
        return rota(*args, **kwargs)
    return dentro

@app.post("/login")
def entrar():
    dado = request.get_json(silent=True) or {}
    u = USUARIOS.get(dado.get("email", ""))
    if u is None or not hmac.compare_digest(u["senha"], dado.get("senha", "")):
        return {"erro": "e-mail ou senha inválidos"}, 401
    return {"token": criar_token(u["id"])}

@app.get("/tarefas")
@exige_login
def listar():
    return [t for t in TAREFAS if t["usuario_id"] == g.uid]

@app.get("/tarefas/<int:id>")
@exige_login
def uma(id):
    t = next((t for t in TAREFAS if t["id"] == id), None)
    if t is None:
        return {"erro": "não encontrada"}, 404
    if t["usuario_id"] != g.uid:
        return {"erro": "sem permissão"}, 403
    return t

