const test = require("node:test");
const assert = require("node:assert/strict");
const crypto = require("node:crypto");
const express = require("express");

const app = express();
app.use(express.json());

const SEGREDO = process.env.APP_SEGREDO ?? "so-para-teste";
const USUARIOS = { "ana@exemplo.com": { id: 7, senha: "senha-boa-123" } };   // simplificado
const TAREFAS = [{ id: 1, usuario_id: 9, titulo: "De outra pessoa" }];

const assinar = (c) => crypto.createHmac("sha256", SEGREDO).update(c).digest("base64url");

function criarToken(uid) {
  const corpo = Buffer.from(JSON.stringify({ sub: uid, exp: Math.floor(Date.now() / 1000) + 3600 })).toString("base64url");
  return `${corpo}.${assinar(corpo)}`;
}

function lerToken(token) {
  const [corpo, assinatura] = String(token).split(".");
  if (!corpo || !assinatura) return null;
  const esperada = Buffer.from(assinar(corpo));
  const recebida = Buffer.from(assinatura);
  if (recebida.length !== esperada.length || !crypto.timingSafeEqual(recebida, esperada)) return null;
  const dados = JSON.parse(Buffer.from(corpo, "base64url").toString());
  return dados.exp < Math.floor(Date.now() / 1000) ? null : dados.sub;
}

function exigeLogin(req, res, proximo) {
  const cabecalho = req.headers.authorization ?? "";
  const uid = cabecalho.startsWith("Bearer ") ? lerToken(cabecalho.slice(7)) : null;
  if (uid === null) return res.status(401).json({ erro: "faça login" });
  req.uid = uid;
  proximo();
}

app.post("/login", (req, res) => {
  const u = USUARIOS[req.body?.email];
  if (!u || u.senha !== req.body?.senha) return res.status(401).json({ erro: "e-mail ou senha inválidos" });
  res.json({ token: criarToken(u.id) });
});

app.get("/tarefas", exigeLogin, (req, res) => {
  res.json(TAREFAS.filter((t) => t.usuario_id === req.uid));
});

app.get("/tarefas/:id", exigeLogin, (req, res) => {
  const t = TAREFAS.find((x) => x.id === Number(req.params.id));
  if (!t) return res.status(404).json({ erro: "não encontrada" });
  if (t.usuario_id !== req.uid) return res.status(403).json({ erro: "sem permissão" });
  res.json(t);
});

// ── o caminho inteiro, num teste só ───────────────────────
test("fluxo completo", async () => {
  const servidor = app.listen(0);
  const base = `http://127.0.0.1:${servidor.address().port}`;
  try {
    assert.equal((await fetch(`${base}/tarefas`)).status, 401);

    const entrar = (senha) =>
      fetch(`${base}/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: "ana@exemplo.com", senha }),
      });

    assert.equal((await entrar("chute")).status, 401);

    const entrada = await entrar("senha-boa-123");
    assert.equal(entrada.status, 200);
    const cabecalho = { Authorization: `Bearer ${(await entrada.json()).token}` };

    const minhas = await fetch(`${base}/tarefas`, { headers: cabecalho });
    assert.deepEqual(await minhas.json(), []);
    assert.equal((await fetch(`${base}/tarefas/1`, { headers: cabecalho })).status, 403);
    assert.equal((await fetch(`${base}/tarefas/99`, { headers: cabecalho })).status, 404);
  } finally {
    servidor.close();
  }
});

