test("fluxo completo", async () => {
  const servidor = app.listen(0);
  const base = `http://127.0.0.1:${servidor.address().port}`;

  try {
    // 1. porta fechada
    assert.equal((await fetch(`${base}/tarefas`)).status, 401);

    const entrar = (senha) =>
      fetch(`${base}/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: "ana@exemplo.com", senha }),
      });

    // 2. senha errada não abre
    assert.equal((await entrar("chute")).status, 401);

    // 3. login certo devolve token
    const entrada = await entrar("senha-boa-123");
    assert.equal(entrada.status, 200);
    const { token } = await entrada.json();
    assert.equal(token.split(".").length, 2);

    const cabecalho = { Authorization: `Bearer ${token}` };

    // 4. com o token, a listagem abre
    assert.equal((await fetch(`${base}/tarefas`, { headers: cabecalho })).status, 200);

    // 5. a tarefa de outra pessoa continua fechada
    assert.equal((await fetch(`${base}/tarefas/1`, { headers: cabecalho })).status, 403);
  } finally {
    servidor.close();
  }
});

